public static class UseFourBoneRoleSkins {public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit required");var rows=new List<object>();string root="Assets/ShooterSurvival/Models/Chapters/Chapters45/DetailedCharacters20261003/",backup="outputs/chapter45-detailed-design-2026-10-03/recovery/four-bone-prefabs";if(Directory.Exists(backup))throw new Exception("Already applied");Directory.CreateDirectory(backup);foreach(var id in new[]{"CH01","CH02","CH03","CH04R","CH05","CH06R","CH07","CH08","CH09","CH10"}){string path=root+id+"/"+id+".prefab";File.Copy(path,backup+"/"+id+".prefab",false);var g=PrefabUtility.LoadPrefabContents(path);try{var skins=g.GetComponentsInChildren<SkinnedMeshRenderer>(true);foreach(var r in skins)r.quality=SkinQuality.Bone4;PrefabUtility.SaveAsPrefabAsset(g,path);rows.Add(new{id,skins=skins.Length,quality="Bone4"});}finally{PrefabUtility.UnloadPrefabContents(g);}}return new{items=rows,projectQualityUnchanged=QualitySettings.skinWeights.ToString(),reason="Actual pose comparison: four influences remove severe shoulder/back wedges; scoped to new role skins only."};}}
